### Python

```python
import sys

def is_lower(c: str) -> bool:
    """判断字符是否为低位形态（小写字母）"""
    return 'a' <= c <= 'z'

def flip(c: str) -> str:
    """翻转形态：高位↔低位"""
    if is_lower(c):
        return chr(ord(c) - 32)   # 低位变高位
    else:
        return chr(ord(c) + 32)   # 高位变低位

def next_same_case(c: str) -> str:
    """同形态后移一位，循环"""
    if is_lower(c):
        return 'a' if c == 'z' else chr(ord(c) + 1)
    else:
        return 'A' if c == 'Z' else chr(ord(c) + 1)

def main() -> None:
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    s = data[1].strip()

    ans = []
    for i in range(n):
        c = s[i]
        if i == 0:
            # 规则：首个字符形态翻转
            ans.append(flip(c))
        else:
            prev = s[i - 1]          # 使用原始字符串中前一字符
            diff = (is_lower(c) != is_lower(prev))
            if diff:
                ans.append(flip(c))
            else:
                ans.append(next_same_case(c))

    print(''.join(ans))

if __name__ == "__main__":
    main()
```

